public class cutlet {
    static int n , k , lo , hi;
    static int[][] segs;
    static int[] l , delt;
    static int[][][] dp;
    static ArrayList<int[]> finSeg = new ArrayList<int[]>();
    public static void main(String[] args) throws IOException {
