#include <bits/stdc++.h>
using namespace std;

/*
TASK: cutlet
LANG: C++
 */

int n, k, lo, hi;
vector<vector<int>> segs;
vector<int> l, delt;
vector<vector<vector<int>>> dp; // 2 x (k+1) x (2*n+1)
vector<array<int,2>> finSeg;

struct RMQ {
    int n, k;
    vector<vector<int>> min;
    RMQ(const vector<int>& a) {
        n = (int)a.size();
        k = std::numeric_limits<int>::max();
        // Compute the highest one bit (log2)
        int temp = n;
        int height = 0;
        while (temp > 0) {
            temp >>= 1;
            height++;
        }
        k = height;

        min.assign(k, vector<int>(n));
        for (int i = 0; i < n; i++) {
            min[0][i] = a[i];
        }
        for (int i = 1; i < k; i++) {
            for (int j = 0; j + (1 << (i - 1)) < n; j++) {
                min[i][j] = std::min(min[i - 1][j], min[i - 1][j + (1 << (i - 1))]);
            }
        }
    }
    int minVal(int a_idx, int b_idx) {
        int length = b_idx - a_idx + 1;
        int z = 31 - __builtin_clz(length); // highestOneBit
        return std::min(min[z][a_idx], min[z][b_idx - (1 << z) + 1]);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> k;
    segs.resize(k, vector<int>(2));
    for (int i = 0; i < k; ++i) {
        cin >> segs[i][0] >> segs[i][1];
    }
    sort(segs.begin(), segs.end(), [](auto &a, auto &b) {
        return a[0] < b[0];
    });
    finSeg.clear();
    for (int i = 0; i < k; ++i) {
        lo = segs[i][0];
        hi = segs[i][0];
        while (i < k && segs[i][0] <= hi) hi = max(hi, segs[i++][1]);
        finSeg.push_back({lo, hi});
        --i; // decrement i because outer loop will increment
    }
    k = (int)finSeg.size();

    segs.assign(k, vector<int>(2));
    l.assign(k, 0);
    delt.assign(k, 0);
    for (int i = 0; i < k; ++i) {
        segs[i] = finSeg[i];
    }
    for (int i = 0; i < k; ++i) {
        l[i] = segs[i][1] - segs[i][0];
        if (i < k - 1)
            delt[i] = segs[i + 1][0] - segs[i][1];
        else
            delt[i] = 2 * n - segs[i][1];
    }

    vector<vector<vector<int>>> dp_curr(2, vector<vector<int>>(k+1, vector<int>(2 * n + 1, n)));
    // Initialize base cases
    for (int i = 0; i <= 2 * n; ++i) {
        dp_curr[0][k][i] = 0;
        dp_curr[1][k][i] = 0;
    }

    for (int j = 0; j <= 2 * n; ++j) {
        dp_curr[1][k][j] = 0;
    }

    vector<RMQ> rmq[2];
    rmq[0] = vector<RMQ>();
    rmq[1] = vector<RMQ>();
    // Initialize RMQ for all rows
    // But as we process backwards, we will instantiate during iteration

    for (int i = k - 1; i >= 0; --i) {
        vector<int> dp0(2 * n + 1, n);
        vector<int> dp1(2 * n + 1, n);
        // prepare for current i
        // initialize RMQ objects for i+1
        vector<int> dp0_next = dp_curr[0][i + 1];
        vector<int> dp1_next = dp_curr[1][i + 1];
        RMQ rmq0(dp0_next);
        RMQ rmq1(dp1_next);
        for (int j = 0; j <= 2 * n; ++j) {
            int val0 = (j + l[i] + delt[i]) <= 2 * n ? dp_curr[0][i + 1][j + l[i] + delt[i]] : n;
            dp0[j] = val0;

            int val1 = dp_curr[1][i + 1][j];
            if (j + delt[i] <= 2 * n) {
                val1 = min(val1, 1 + rmq0.minVal(j + delt[i], min(j + l[i] + delt[i], 2 * n)));
                val1 = min(val1, 2 + rmq0.minVal(j + delt[i], min(j + l[i] + delt[i], 2 * n)));
            }

            int val0_alt = 1 + rmq1.minVal(j, min(j + l[i], 2 * n));
            int val0_alt2 = 2 + (j + delt[i] <= 2 * n ? rmq0.minVal(j + delt[i], min(j + l[i] + delt[i], 2 * n)) : n);

            dp0[j] = min(dp0[j], val0_alt2, val0_alt);
            if (j + delt[i] <= 2 * n) {
                dp1[j] = min(dp_curr[1][i + 1][j], 1 + rmq0.minVal(j + delt[i], min(j + l[i] + delt[i], 2 * n)), 2 + rmq1.minVal(j, min(j + l[i], 2 * n)));
            } else {
                dp1[j] = dp_curr[1][i + 1][j];
            }
        }
        // update for next iteration
        for (int j = 0; j <= 2 * n; ++j) {
            dp_curr[0][i][j] = dp0[j];
            dp_curr[1][i][j] = dp1[j];
        }
    }

    int ans = dp_curr[1][0][0];

    if (ans == n) {
        cout << "Hungry\n";
    } else {
        cout << "Full\n" << ans << "\n";
    }

    return 0;
}
